// Screenshots de showcase embutidos como base64 — Hostinger não serve public/.
//
// Capturas reais do painel (agosto/2026), recortadas para remover a barra
// lateral — ela expunha nome e e-mail da conta. Todo número citado na landing
// tem de estar visível na captura correspondente; ver components/landing/LandingSections.tsx.
const SHOWCASE: Record<string, { mime: string; data: string }> = {
  'visao-geral.jpg': { mime: 'image/jpeg', data: '' },
  'leads.jpg': { mime: 'image/jpeg', data: '' },
  'funil-conversao.jpg': { mime: 'image/jpeg', data: '' },
  'analytics.jpg': { mime: 'image/jpeg', data: '' },
  'sara-insights.jpg': { mime: 'image/jpeg', data: '' },
}
export const dynamic = 'force-dynamic'

export async function GET(
  _req: Request,
  { params }: { params: Promise<{ name: string }> }
) {
  const { name } = await params
  // Object.hasOwn e não truthiness: `SHOWCASE['constructor']` herda do protótipo,
  // passava no `if (!entry)` e estourava 500 em `Buffer.from(undefined)`.
  if (!Object.hasOwn(SHOWCASE, name)) return new Response(null, { status: 404 })
  const entry = SHOWCASE[name]
  const buf = Buffer.from(entry.data, 'base64')
  return new Response(buf, {
    headers: {
      'Content-Type': entry.mime,
      'Cache-Control': 'public, max-age=31536000, immutable',
      'Content-Length': String(buf.length),
    },
  })
}
